(window.__qhadithX=window.__qhadithX||{})[50]={"9":[{"c":"Al-Adab Al-Mufrad","r":"Book 50, Hadith 1228","u":"https://quranx.com/Hadith/Adab/English/Book-50/Hadith-1228","x":"Abu Mulayka related that when it rained, Ibn 'Abbas said, \"Slavegirl! Bring out my saddle and bring my garment. Allah says, 'We sent down blessed water from the sky.' (50:9)\"","ar":"حَدَّثَنَا بِشْرُ بْنُ الْحَكَمِ، قَالَ‏:‏ حَدَّثَنَا مُحَمَّدُ بْنُ رَبِيعَةَ، عَنِ السَّائِبِ بْنِ عُمَرَ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ كَانَ إِذَا مَطَرَتِ السَّمَاءُ يَقُولُ‏:‏ يَا جَارِيَةُ، أَخْرِجِي سَرْجِي، أَخْرِجِي ثِيَابِي، وَيَقُولُ‏:‏ ‏{‏وَنَزَّلْنَا مِنَ السَّمَاءِ مَاءً مُبَارَكًا‏}‏‏.‏","v":[]}],"10":[{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 816","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-816","x":"It was narrated from Qutbah bin Malik that he heard the Prophet (ﷺ) recite:\n\n\"And tall date palms, with ranged clusters\" [50:10] in the Subh.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا شَرِيكٌ، وَسُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنْ قُطْبَةَ بْنِ مَالِكٍ، سَمِعَ النَّبِيَّ ـ صلى الله عليه وسلم ـ يَقْرَأُ فِي الصُّبْحِ ‏{وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ }‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 457a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-457a","x":"Qutba b. Malik reported:\n\nI said prayer and the Messenger of Allah (ﷺ) led it and he recited\" Qaf. (I.). By the Glorious Qur'an,\" till he recited\" and the tall palm trees\" (l. 10). I wanted to repeat it but I could not follow its significance.","ar":"حَدَّثَنِي أَبُو كَامِلٍ الْجَحْدَرِيُّ، فُضَيْلُ بْنُ حُسَيْنٍ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنْ قُطْبَةَ بْنِ مَالِكٍ، قَالَ صَلَّيْتُ وَصَلَّى بِنَا رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَرَأَ ‏{‏ ق وَالْقُرْآنِ الْمَجِيدِ‏}‏ حَتَّى قَرَأَ ‏{‏ وَالنَّخْلَ بَاسِقَاتٍ‏}‏ قَالَ فَجَعَلْتُ أُرَدِّدُهَا وَلاَ أَدْرِي مَا قَالَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 457b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-457b","x":"Qutba b. Malik reported that he had heard the Messenger of Allah (ﷺ) reciting in the morning prayer this:\n\n\" And the tall palm trees having flower spikes piled one above another\" (Al-Qur'an 50:10).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا شَرِيكٌ، وَابْنُ، عُيَيْنَةَ ح وَحَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا ابْنُ عُيَيْنَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنْ قُطْبَةَ بْنِ مَالِكٍ، سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقْرَأُ فِي الْفَجْرِ ‏{‏ وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 457c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-457c","x":"Ziyad b. 'Ilaqa reported it on the authority of his uncle that he said the morning prayer with the Messenger of Allah (ﷺ) and he recited in the first rak'ah:\n\n\"And the tall palm trees having flower spikes piled one above another (l. 10) or perhaps Surah Qaf.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنْ عَمِّهِ، أَنَّهُ صَلَّى مَعَ النَّبِيِّ صلى الله عليه وسلم الصُّبْحَ فَقَرَأَ فِي أَوَّلِ رَكْعَةٍ ‏{‏ وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ‏}‏ وَرُبَّمَا قَالَ ‏{‏ ق‏}‏ ‏.‏","v":[]}],"30":[{"c":"Sahih Bukhari","r":"Hadith 4848","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4848","x":"Narrated Anas:\n\nThe Prophet (ﷺ) said, \"The people will be thrown into the (Hell) Fire and it will say: \"Are there any more (to come)?' (50.30) till Allah puts His Foot over it and it will say, 'Qati! Qati! (Enough Enough!)'\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَبِي الأَسْوَدِ، حَدَّثَنَا حَرَمِيٌّ، حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ يُلْقَى فِي النَّارِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ‏.‏ حَتَّى يَضَعَ قَدَمَهُ فَتَقُولُ قَطِ قَطِ ‏\"\n\n‏‏.‏","v":[]}],"39":[{"c":"Sahih Bukhari","r":"Hadith 554","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-554","x":"Narrated Qais:\n\nJarir said, \"We were with the Prophet (ﷺ) and he looked at the moon--full-moon--and said, 'Certainly you will see your Lord as you see this moon and you will have no trouble in seeing Him. So if you can avoid missing (through sleep or business, etc.) a prayer before the sunrise (Fajr) and a prayer before sunset (`Asr), you must do so.' He then recited Allah's Statement: And celebrate the praises Of your Lord before the rising of the sun and before (its) setting.\" (50.39) Isma`il said, \"Offer those prayers and do not miss them.\"","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، قَالَ حَدَّثَنَا مَرْوَانُ بْنُ مُعَاوِيَةَ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ، عَنْ قَيْسٍ، عَنْ جَرِيرٍ، قَالَ كُنَّا عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةً ـ يَعْنِي الْبَدْرَ ـ فَقَالَ ‏\"‏ إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لاَ تُضَامُّونَ فِي رُؤْيَتِهِ، فَإِنِ اسْتَطَعْتُمْ أَنْ لاَ تُغْلَبُوا عَلَى صَلاَةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ‏\"‏‏.‏ ثُمَّ قَرَأَ ‏{‏وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ‏}‏‏.‏ قَالَ إِسْمَاعِيلُ افْعَلُوا لاَ تَفُوتَنَّكُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 573","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-573","x":"Narrated Jarir bin `Abdullah:\n\nWe were with the Prophet (ﷺ) on a full moon night. He looked at the moon and said, \"You will certainly see your Lord as you see this moon, and there will be no trouble in seeing Him. So if you can avoid missing (through sleep, business, etc.) a prayer before the rising of the sun (Fajr) and before its setting (`Asr) you must do so. He (the Prophet (ﷺ) ) then recited the following verse: And celebrate the praises Of Your Lord before The rising of the sun And before (its) setting.\" (50.39)","ar":"حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا يَحْيَى، عَنْ إِسْمَاعِيلَ، حَدَّثَنَا قَيْسٌ، قَالَ لِي جَرِيرُ بْنُ عَبْدِ اللَّهِ كُنَّا عِنْدَ النَّبِيِّ صلى الله عليه وسلم إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ ‏\"‏ أَمَا إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا، لاَ تُضَامُّونَ ـ أَوْ لاَ تُضَاهُونَ ـ فِي رُؤْيَتِهِ، فَإِنِ اسْتَطَعْتُمْ أَنْ لاَ تُغْلَبُوا عَلَى صَلاَةٍ قَبْلَ طُلُوعِ الشَّمْسِ، وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ‏\"‏‏.‏ ثُمَّ قَالَ ‏\"‏ فَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4851","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4851","x":"Narrated Jarir bin `Abdullah:\n\nWe were in the company of the Prophet (ﷺ) on a fourteenth night (of the lunar month), and he looked at the (full) moon and said, \"You will see your Lord as you see this moon, and you will have no trouble in looking at Him. So, whoever can, should not miss the offering of prayers before sunrise (Fajr prayer) and before sunset (`Asr prayer).\" Then the Prophet (ﷺ) recited: 'And celebrate the praises of your Lord before the rising of the sun and before (its) setting.' (50.39)","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، عَنْ جَرِيرٍ، عَنْ إِسْمَاعِيلَ، عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ، عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا جُلُوسًا لَيْلَةً مَعَ النَّبِيِّ صلى الله عليه وسلم فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةَ أَرْبَعَ عَشْرَةَ فَقَالَ ‏\"‏ إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا، لاَ تُضَامُونَ فِي رُؤْيَتِهِ، فَإِنِ اسْتَطَعْتُمْ أَنْ لاَ تُغْلَبُوا عَلَى صَلاَةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ‏\"‏‏.‏ ثُمَّ قَرَأَ ‏{‏وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ‏}‏","v":[]}],"40":[{"c":"Sahih Bukhari","r":"Hadith 4852","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4852","x":"Narrated Mujahid:\n\nIbn `Abbas said, \"Allah ordered His Prophet to celebrate Allah's praises after all prayers.\" He refers to His Statement: 'After the prayers.' (50.40)","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا وَرْقَاءُ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، قَالَ ابْنُ عَبَّاسٍ أَمَرَهُ أَنْ يُسَبِّحَ، فِي أَدْبَارِ الصَّلَوَاتِ كُلِّهَا‏.‏ يَعْنِي قَوْلَهُ ‏{‏وَأَدْبَارَ السُّجُودِ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3275","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3275","x":"Narrated Ibn 'Umar:\n\nthat the Prophet (ﷺ) said: \"And at the setting of the stars (52:49) (about) the two Rak'ah before Fajr. And after the prostrations (50:40) 'The two Rak'at after Al-Maghrib.'\"","ar":"حَدَّثَنَا أَبُو هِشَامٍ الرِّفَاعِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، عَنْ رِشْدِينَ بْنِ كُرَيْبٍ، عَنْ أَبِيهِ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ إِدْبَارُ النُّجُومِ الرَّكْعَتَانِ قَبْلَ الْفَجْرِ وَإِدْبَارُ السُّجُودِ الرَّكْعَتَانِ بَعْدَ الْمَغْرِبِ ‏\"\n\n‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ مَرْفُوعًا إِلاَّ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ مُحَمَّدِ بْنِ فُضَيْلٍ عَنْ رِشْدِينَ بْنِ كُرَيْبٍ ‏.‏ قَالَ أَبُو عِيسَى وَسَأَلْتُ مُحَمَّدَ بْنَ إِسْمَاعِيلَ عَنْ مُحَمَّدٍ وَرِشْدِينَ ابْنَىْ كُرَيْبٍ أَيُّهُمَا أَوْثَقُ قَالَ مَا أَقْرَبَهُمَا وَمُحَمَّدٌ عِنْدِي أَرْجَحُ ‏.‏ قَالَ وَسَأَلْتُ عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ عَنْ هَذَا فَقَالَ مَا أَقْرَبَهُمَا عِنْدِي وَرِشْدِينُ بْنُ كُرَيْبٍ أَرْجَحُهُمَا عِنْدِي ‏.‏ قَالَ وَالْقَوْلُ عِنْدِي مَا قَالَ أَبُو مُحَمَّدٍ وَرِشْدِينُ أَرْجَحُ مِنْ مُحَمَّدٍ وَأَقْدَمُ وَقَدْ أَدْرَكَ رِشْدِينُ ابْنَ عَبَّاسٍ وَرَآهُ ‏.‏","v":[]}]};